describe('Debounced Search Functionality', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should trigger search after 300ms of inactivity', () => {
        cy.get('input[name="search"]')
            .type('Cypress')
            .wait(300) // Wait for debounce time
            .then(() => {
                cy.get('.search-results').should('exist'); // Check if results are displayed
                cy.get('.search-results').should('contain', 'Cypress'); // Check if results contain the search term
            });
    });

    it('should not trigger search if typing continues within 300ms', () => {
        cy.get('input[name="search"]')
            .type('Cypress')
            .wait(100) // Wait for less than debounce time
            .type(' Testing')
            .wait(300) // Wait for debounce time after typing
            .then(() => {
                cy.get('.search-results').should('not.exist'); // Ensure no results are displayed
            });
    });
});
